#!/usr/bin/env bash
# Partie « Légal et RGPD » : carte des entités et parcours (documents légaux et données, droit à l'image).
# Analyse : cascades du schéma, lectures imbriquées, gardes admin en tête de corps.
# Prérequis : apply-docs-pastilles.sh.
# Usage (racine du repo) : bash apply-carte-legal.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/legal/documents-legaux-et-donnees.mdx" 2>/dev/null | grep -qF "La purge de la nuit"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "max-lg:sr-only" "apps/web/src/features/docs/components/DocsRightAsideDrawer.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-pastilles.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/content/docs/dev/legal/documents-legaux-et-donnees.mdx" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" "apps/web/src/features/docs/entities/EntityExplorer.tsx" "apps/web/src/features/docs/entities/stories.ts" "scripts/build-procedure-map.mjs" "apps/web/src/features/docs/entities/procedureMap.generated.json")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "La purge de la nuit" "apps/web/content/docs/dev/legal/documents-legaux-et-donnees.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/docs/entities"
base64 -d > "apps/web/src/features/docs/entities/procedureMap.generated.json" <<'B64'
